#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 1e5 + 5;
const int L = 18;

int n, q;
int h[N], nx[N];
int par[L][N], son[L][N];

void dfs(int u) {
    for (int i = 1; i < L; i++)
        par[i][u] = par[i - 1][par[i - 1][u]];
    son[0][u] = u;
    for (int i = h[u]; i; i = nx[i]) {
        dfs(i);
        if (son[0][u] == u || i < son[0][u])
            son[0][u] = i;
    }
    for (int i = 1; i < L; i++)
        son[i][u] = son[i - 1][son[i - 1][u]];
}

int move(int go[L][N], int u, int step) {
    for (int i = 0; i < L; i++)
        if ((step >> i) & 1)
            u = go[i][u];
    return u;
}

int main() {
    scanf("%d%d", &n, &q);
    for (int i = 2; i <= n; i++) {
        scanf("%d", &par[0][i]);
        nx[i] = h[par[0][i]];
        h[par[0][i]] = i;
    }
    par[0][1] = 1;
    dfs(1);
    while (q--) {
        int s, k;
        scanf("%d%d", &s, &k);
        while (k--) {
            int a;
            scanf("%d", &a);
            if (a < 0)
                s = move(son, s, -a);
            else
                s = move(par, s, a);
        }
        printf("%d\n", s);
    }
    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 1e5 + 5;
const int mod = 1e9;

int n, deg[N], fac[N];
int pre[N], suf[N];
int ans;

int main() {
    scanf("%d", &n);
    fac[0] = 1;
    for (int i = 1; i <= n; i++)
        fac[i] = 1ll * fac[i - 1] * i % mod;
    for (int i = 1; i < n; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        deg[u]++;
        deg[v]++;
    }
    pre[0] = 1;
    for (int i = 1; i <= n; i++)
        pre[i] = 1ll * pre[i - 1] * fac[deg[i] - 1] % mod;
    suf[n + 1] = 1;
    for (int i = n; i; i--)
        suf[i] = 1ll * suf[i + 1] * fac[deg[i] - 1] % mod;
    for (int i = 1; i <= n; i++)
        ans = (ans + 1ll * pre[i - 1] * fac[deg[i]] % mod * suf[i + 1]) % mod;
    printf("%d\n", ans);
    return 0;
}
